#!/usr/bin/env node
// Writes docs/API.md from the OpenAPI document of the API (packages/shared/openapi/openapi.json).
// Run by `pnpm api:types` after the document is exported; do not edit docs/API.md by hand.
//
// Who may call each route comes from `x-access`, `x-roles` and `x-verified-email`, which
// the API adds from the guards' metadata (apps/api/src/common/swagger/access-extension.ts).
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const source = resolve(root, 'packages/shared/openapi/openapi.json');
const target = resolve(root, 'docs/API.md');
const document = JSON.parse(readFileSync(source, 'utf8'));

const ROLE_NAMES = {
  CANDIDATE: 'candidate',
  VIEWER: 'viewer',
  RECRUITER: 'recruiter',
  SUPER_ADMIN: 'super admin',
};
const METHODS = ['get', 'post', 'put', 'patch', 'delete'];

function access(operation) {
  const roles = (operation['x-roles'] ?? []).map((role) => ROLE_NAMES[role] ?? role);
  let text;
  switch (operation['x-access']) {
    case 'public':
      text = 'Public';
      break;
    case 'session':
      text = 'Signed in';
      break;
    case 'roles':
      text =
        roles.length === 1
          ? `${roles[0][0].toUpperCase()}${roles[0].slice(1)} only`
          : roles.join(', ');
      text = text[0].toUpperCase() + text.slice(1);
      break;
    default:
      text = '?';
  }
  return operation['x-verified-email'] ? `${text}, verified email` : text;
}

const cell = (value) =>
  String(value ?? '')
    .replaceAll('|', '\\|')
    .replaceAll('\n', ' ');

const groups = new Map();
for (const [path, item] of Object.entries(document.paths)) {
  for (const method of METHODS) {
    const operation = item[method];
    if (!operation) {
      continue;
    }
    const tag = operation.tags?.[0] ?? 'other';
    if (!groups.has(tag)) {
      groups.set(tag, []);
    }
    groups.get(tag).push({ method: method.toUpperCase(), path, operation });
  }
}

const order = (tag) =>
  tag === 'health'
    ? 0
    : tag === 'public'
      ? 1
      : tag === 'auth'
        ? 2
        : tag.startsWith('candidate')
          ? 3
          : 4;
const tags = [...groups.keys()].sort((a, b) => order(a) - order(b) || a.localeCompare(b));
const count = [...groups.values()].reduce((sum, list) => sum + list.length, 0);
const codes =
  document.components?.schemas?.ApiError?.properties?.code?.enum ??
  Object.values(document.paths)
    .flatMap((item) => METHODS.map((method) => item[method]).filter(Boolean))
    .flatMap((operation) => Object.values(operation.responses ?? {}))
    .map((response) => response.content?.['application/json']?.schema?.properties?.code?.enum)
    .find(Array.isArray) ??
  [];

const lines = [
  '# API',
  '',
  '<!-- Generated by scripts/api-doc.mjs from packages/shared/openapi/openapi.json (pnpm api:types). Do not edit by hand. -->',
  '',
  `${document.info.title}, version ${document.info.version}: ${count} operations. The interactive reference (Swagger UI) is at \`/api/docs\` on the API (<http://localhost:4000/api/docs> locally); in Azure the API has no public address, and the browser reaches it only through the web app under \`/api/v1/*\`.`,
  '',
  '## Conventions',
  '',
  '- **Base path** `/api/v1`, JSON in and out (file uploads: `multipart/form-data`; exports: CSV or Excel). Health probes `/health/live` and `/health/ready` sit outside it.',
  '- **Sessions**: `POST /api/v1/auth/login` sets two `HttpOnly`, `Secure`, `SameSite=Lax` cookies: a 15-minute access token and a refresh token (`POST /api/v1/auth/refresh`). No bearer header.',
  '- **Writes from a browser** must come from the site itself: a request whose `Origin` is another site is refused (CSRF origin check).',
  '- **Validation**: every body, query and path parameter is checked with a zod schema of `packages/shared`; the typed client `@iconbridge/shared/api-client` is generated from this document.',
  '- **Errors** always answer `{ code, message, details? }` with no stack trace. Rate-limited routes (sign-in, registration, forms) answer `429` with `RATE_LIMITED`.',
  '- **Access** below comes from the guards themselves: _Public_ needs no session; _Signed in_ any role; otherwise only the roles listed (SPEC section 2). _Verified email_ also requires a confirmed address. Back-office routes live under `/api/v1/admin`.',
  '',
  `Error codes: ${codes.map((code) => `\`${code}\``).join(', ')}.`,
  '',
];

for (const tag of tags) {
  lines.push(`## ${tag[0].toUpperCase()}${tag.slice(1)}`, '');
  lines.push('| Method | Path | What | Access |', '| --- | --- | --- | --- |');
  for (const { method, path, operation } of groups.get(tag)) {
    lines.push(
      `| ${method} | \`${cell(path)}\` | ${cell(operation.summary)} | ${cell(access(operation))} |`,
    );
  }
  lines.push('');
}

writeFileSync(target, lines.join('\n'));
process.stdout.write(`docs/API.md written: ${count} operations in ${tags.length} groups\n`);
